// Minh họa Zero-cost Ownership và Compile-time Memory Safety
struct NetworkConnection {
    fd: i32,
}

impl Drop for NetworkConnection {
    fn drop(&mut self) {
        // Tự động giải phóng tài nguyên khi ra khỏi scope mà không cần GC hay gọi free thủ công
        println!("Closing connection socket fd: {}", self.fd);
    }
}

fn handle_connection(conn: NetworkConnection) {
    println!("Processing connection on fd: {}", conn.fd);
} // conn ra khỏi scope tại đây -> Drop::drop tự động kích hoạt!

fn main() {
    let conn = NetworkConnection { fd: 42 };
    handle_connection(conn); // Quyền sở hữu (Ownership) được chuyển giao (Move)

    // conn.fd; // LỖI BIÊN DỊCH: Use of moved value: `conn`!
    // Trình biên dịch Rust ngăn chặn lỗi Use-After-Free ngay lúc compile!
    println!("Main thread finishes cleanly without GC overhead.");
}

