struct MetricData {
    value: f64,
}

// Hàm nhận Shared Reference (&T): Chỉ đọc, an toàn cho nhiều caller
fn inspect_metric(metric: &MetricData) {
    println!("Current metric value: {:.2}", metric.value);
}

// Hàm nhận Mutable Reference (&mut T): Độc quyền sửa đổi
fn calibrate_metric(metric: &mut MetricData, offset: f64) {
    metric.value += offset;
}

fn main() {
    let mut cpu_metric = MetricData { value: 85.5 };

    // Nhiều Shared References cùng tồn tại hợp lệ
    let ref1 = &cpu_metric;
    let ref2 = &cpu_metric;
    inspect_metric(ref1);
    inspect_metric(ref2);
    // ref1 và ref2 kết thúc vòng đời sử dụng tại đây (NLL)

    // Mutable Reference độc quyền được tạo ra
    let mut_ref = &mut cpu_metric;
    calibrate_metric(mut_ref, 2.5);

    println!("Calibrated: {:.2}", cpu_metric.value);
}

