use std::fmt::Display;

// Định nghĩa Trait: Hợp đồng lưu trữ dữ liệu
trait StorageBackend {
    fn write_record(&mut self, id: u64, data: &[u8]) -> Result<(), String>;

    // Default implementation
    fn flush(&mut self) -> Result<(), String> {
        println!("Default flush executed");
        Ok(())
    }
}

// Triển khai Trait cho LocalFileStorage
struct LocalFileStorage;
impl StorageBackend for LocalFileStorage {
    fn write_record(&mut self, id: u64, data: &[u8]) -> Result<(), String> {
        println!("Writing {} bytes for id {} to Local Disk", data.len(), id);
        Ok(())
    }
}

// Sử dụng Trait Bounds: Static Dispatch O(0) runtime cost
fn persist_metrics<S: StorageBackend, D: Display>(storage: &mut S, id: u64, desc: D) {
    println!("Audit log: {}", desc);
    let payload = [1, 2, 3, 4];
    storage.write_record(id, &payload).expect("Write failed");
    storage.flush().expect("Flush failed");
}

