}

trait PacketFilter {
    fn filter(&self, packet_id: u32) -> bool;
}

struct AllowAllFilter;
impl PacketFilter for AllowAllFilter {
    fn filter(&self, _id: u32) -> bool { true }
}

struct BlockListFilter;
impl PacketFilter for BlockListFilter {
    fn filter(&self, id: u32) -> bool { id != 999 }
}

// 1. Static Dispatch: Inlining trực tiếp, Zero runtime cost, mã máy chuyên biệt hóa
fn run_static_pipeline(filter: &impl PacketFilter, id: u32) {
    let allowed = filter.filter(id); // Direct call
    println!("Static filter result: {}", allowed);
}

// 2. Dynamic Dispatch: Trait Object qua Fat Pointer (&dyn Trait)
fn run_dynamic_pipeline(filters: &[Box<dyn PacketFilter>], id: u32) {
    for f in filters {
        // Indirect call qua vtable, cho phép chứa các struct khác nhau trong cùng 1 Vec
        if !f.filter(id) {
            println!("Packet {} blocked by dynamic filter!", id);
            return;
        }
    }
    println!("Packet {} passed all dynamic filters", id);
}

fn main() {
    let allow = AllowAllFilter;
    run_static_pipeline(&allow, 100);

    // Mảng chứa các đối tượng có kiểu cụ thể khác nhau nhờ dyn Trait
    let dynamic_filters: Vec<Box<dyn PacketFilter>> = vec![
        Box::new(AllowAllFilter),
        Box::new(BlockListFilter),
    ];
    run_dynamic_pipeline(&dynamic_filters, 999);
}

