// 1. RefCell trong Đơn luồng: Cho phép sửa đổi trạng thái qua &self
trait Logger {
    fn log(&self, message: &str);
}

struct MockLogger {
    // Dùng RefCell để lưu trữ lịch sử log dù API chỉ có &self
    logs: RefCell<Vec<String>>,
};

impl Logger for MockLogger {
    fn log(&self, message: &str) {
        // borrow_mut() thực hiện kiểm tra động tại runtime
        self.logs.borrow_mut().push(message.to_string());
    }
}

fn main() {
    let logger = MockLogger { logs: RefCell::new(vec![]) };
    logger.log("First telemetry packet");
    logger.log("Second packet received");
    println!("Logged items count: {}", logger.logs.borrow().len()); // 2

    // 2. Mutex trong Đa luồng: Khóa đồng bộ an toàn
    let thread_safe_counter = Mutex::new(0);
    {
        let mut guard = thread_safe_counter.lock().unwrap();
        *guard += 1; // Mutate dữ liệu an toàn
    } // Guard tự động unlock khi ra khỏi scope
    println!("Counter: {}", *thread_safe_counter.lock().unwrap());
}

use std::sync::{Arc, Mutex};
use std::thread;

// Struct tự động implement Send + Sync vì tất cả các trường đều là Send + Sync
struct JobPayload {
    job_id: u64,
    data: Vec<u8>,
}

fn main() {
    // Arc<Mutex<T>> biến một kiểu T (chỉ cần Send) thành Sync để chia sẻ đa luồng
    let shared_state = Arc::new(Mutex::new(JobPayload {
        job_id: 1,
        data: vec![0xAA, 0xBB],
    }));

    let mut handles = vec![];

    for i in 0..3 {
        let state_clone = Arc::clone(&shared_state); // Arc là Send + Sync
        let handle = thread::spawn(move || {
            let mut guard = state_clone.lock().unwrap();
            guard.job_id += 1;
            println!("Thread {} updated job_id to: {}", i, guard.job_id);
        });
        handles.push(handle);
    }

    for h in handles {
        h.join().unwrap();
    }
}

use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll};

// Tự triển khai một Future tối giản để thấy rõ cơ chế Pull-based
struct CountdownFuture {
    remaining_polls: usize,
}

impl Future for CountdownFuture {
    type Output = &'static str;

    // Phương thức poll được Executor 'kéo' (Pull) khi có tín hiệu sẵn sàng
    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        if self.remaining_polls == 0 {
            Poll::Ready("Countdown complete!")
        } else {
            self.remaining_polls -= 1;
            println!("Polled: remaining polls = {}", self.remaining_polls);

            // Đánh thức chính mình để Executor poll lần tiếp theo
            cx.waker().wake_by_ref();
            Poll::Pending
        }
    }
}

// Trong Rust, gọi hàm async không làm gì cho đến khi có .await (Lazy)
async fn run_task() {
    let future = CountdownFuture { remaining_polls: 2 };
    println!("Future created but nothing has executed yet!");

    let result = future.await; // Bắt đầu được Executor kéo và thực thi
    println!("Task finished: {}", result);
}

fn main() {
    // Cần một Executor (như Tokio) để chạy async block
    tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .unwrap()
        .block_on(run_task());
}

use tokio::time::{sleep, Duration};

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() {
    println!("Starting Tokio multi-threaded work-stealing runtime...");

    let mut task_handles = vec![];

    // Spawn 10 tasks đồng thời: Tokio scheduler sẽ tự động phân phối và work-steal
    for task_id in 0..10 {
        let handle = tokio::spawn(async move {
            println!("Task {} running on thread: {:?}", task_id, std::thread::current().id());
            // Giả lập I/O chờ không chặn luồng
            sleep(Duration::from_millis(50)).await;
            task_id * 2
        });
        task_handles.push(handle);
    }

    for h in task_handles {
        let res = h.await.unwrap();
        println!("Completed result: {}", res);
    }
}

