// Xây dựng một Safe Abstraction bọc quanh khối Unsafe thao tác con trỏ thô
struct CustomBox<T> {
    ptr: *mut T, // Con trỏ thô (Raw pointer)
}

impl<T> CustomBox<T> {
    pub fn new(val: T) -> Self {
        let boxed = Box::new(val);
        Self {
            ptr: Box::into_raw(boxed),
        }
    }

    // Giao diện Safe 100% cho người dùng bên ngoài
    pub fn get(&self) -> &T {
        // Siêu năng lực 1: Dereference con trỏ thô bên trong khối unsafe
        unsafe { &*self.ptr }
    }
}

impl<T> Drop for CustomBox<T> {
    fn drop(&mut self) {
        // Siêu năng lực 2: Gọi hàm unsafe Box::from_raw để thu hồi bộ nhớ Heap sạch sẽ
        unsafe {
            drop(Box::from_raw(self.ptr));
        }
    }
}

fn main() {
    let safe_box = CustomBox::new(42);
    println!("Value safely accessed from custom box: {}", safe_box.get());
}

