        return -1;
    }

    // Chuyển đổi an toàn từ C const char* sang Rust &str
    let c_str = unsafe { CStr::from_ptr(input) };
    match c_str.to_str() {
        Ok(rust_str) => {
            println!("Rust received string from C: {}", rust_str);
            rust_str.len() as c_int
        }
        Err(_) => -2,
    }
}

fn main() {
    // Gọi hàm C puts an toàn từ Rust bằng CString
    let message = CString::new("Calling C puts from Rust FFI!").unwrap();
    unsafe {
        puts(message.as_ptr());
    }
}

// Thuật toán tính tích vô hướng của 2 vector: Trừu tượng bậc cao nhưng tối ưu mã máy tối đa
pub fn dot_product(a: &[f32], b: &[f32]) -> f32 {
    // Chuỗi Iterator này được LLVM inline phẳng hoàn toàn,
    // loại bỏ bounds check và tự động vector hóa thành các lệnh AVX/SIMD vector instructions!
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| x * y)
     .sum()
}

fn main() {
    let vec_a = [1.0, 2.0, 3.0, 4.0];
    let vec_b = [0.5, 1.5, 2.5, 3.5];

    let result = dot_product(&vec_a, &vec_b);
    println!("Dot product: {}", result); // In ra 25.0

    // Khi biên dịch với flag: RUSTFLAGS="-C target-cpu=native -O"
    // Hàm trên biên dịch thẳng thành một lệnh SIMD nhân cộng (FMA/AVX) duy nhất!
}

// 1. Declarative Macro: macro_rules! tạo cú pháp ngắn gọn xây dựng HashMap
macro_rules! map_builder {
    ( $( $key:expr => $val:expr ),* $(,)? ) => {{
        let mut map = std::collections::HashMap::new();
        $(
            map.insert($key, $val);
        )*
        map
    }};
}

fn main() {
    // Sử dụng Declarative Macro trực quan
    let status_codes = map_builder! {
        200 => "OK",
        404 => "Not Found",
        500 => "Internal Server Error",
    };

    println!("Status 200: {}", status_codes[&200]);

