use std::cell::RefCell;
use std::rc::{Rc, Weak};

struct Node {
    id: usize,
    // DÙNG WEAK ĐỂ PHÒNG TRÁNH LEAK:
    // Thay vì Rc<RefCell<Option<Rc<Node>>>> (gây reference cycle),
    // ta dùng Weak trỏ ngược về cha!
    parent: RefCell<Weak<Node>>,
    children: RefCell<Vec<Rc<Node>>>,
}

fn main() {
    // Node cha
    let leaf = Rc::new(Node {
        id: 1,
        parent: RefCell::new(Weak::new()),
        children: RefCell::new(vec![]),
    });

    let branch = Rc::new(Node {
        id: 2,
        parent: RefCell::new(Weak::new()),
        children: RefCell::new(vec![Rc::clone(&leaf)]),
    });

    // Gán parent bằng Weak reference: Không tăng strong count của branch!
    *leaf.parent.borrow_mut() = Rc::downgrade(&branch);

    println!("Branch strong count: {}", Rc::strong_count(&branch)); // 1
    println!("Leaf strong count: {}", Rc::strong_count(&leaf));     // 2

    // Truy cập parent an toàn qua .upgrade()
    if let Some(parent_rc) = leaf.parent.borrow().upgrade() {
        println!("Leaf's parent ID is: {}", parent_rc.id);
    }

    // Khi branch và leaf ra khỏi scope, toàn bộ bộ nhớ được giải phóng 100% sạch sẽ!
}
